window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-578963c34d036c12"]={"versions": [{"id": "FIG-578963c34d036c12", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR ECU-Konfigurations-Klassendiagramm (UML-Metamodell nach Ecuc-Schema) kombiniert mit einer tabellarischen Moduldefinition für das Classic-Platform-Basiselement <code>LinNm</code> (LIN Network Management). Die Darstellung definiert die hierarchische Container-Struktur der Konfigurationsparameter auf oberster Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Metadatentabellen und eine dreistufige Kompositionskette von Konfigurationselementen:</p>\n<ul class=\"fig-list\"><li>Kopfzeile: Modulname <code>LinNm</code>, Modulbeschreibung „Configuration Parameters for the Lin Nm module.“.\n</li><li>Tabelle „Included Containers“:\n<ul class=\"fig-list\"><li><code>LinNmGlobalConfig</code>: Multiplicity 1, Scope / Dependency „This container contains the global configuration parameter of the LinNm.“.\n</li></ul>\n</li><li>UML-Klassenhierarchie:\n<ul class=\"fig-list\"><li><code>LinNm : EcucModuleDef</code>: Wurzelmoduldefinition mit Attributen <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li>Kompositionsbeziehung (ausgefüllte Raute) mit Rollenbezeichnung <code>+container</code> zu <code>LinNmGlobalConfig : EcucParamConfContainerDef</code>.\n</li><li>Kompositionsbeziehung mit Rollenbezeichnung <code>+subContainer</code> von <code>LinNmGlobalConfig</code> zu <code>LinNmChannelConfig : EcucParamConfContainerDef</code> mit Attributen <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungssemantik oder Laufzeitsequenzen. Die Struktur definiert die Kardinalitätsgrenzen und Schachtelungsregeln für die Instanziierung zur Generierungs-/Konfigurationszeit: Ein <code>LinNm</code>-Modul enthält genau einen globalen Konfigurationscontainer <code>LinNmGlobalConfig</code>, welcher wiederum mindestens einen oder mehrere (<code>1..*</code>) kanalspezifische Container (<code>LinNmChannelConfig</code>) als Sub-Container umfasst.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsspezifikation für AUTOSAR-Werkzeugketten und den LIN-NM-Stack:</p>\n<ul class=\"fig-list\"><li><code>LinNmGlobalConfig</code> ist obligatorisch (<code>Multiplicity = 1</code>).\n</li><li><code>LinNmChannelConfig</code> erfordert für jeden angebundenen LIN-Cluster mindestens eine Instanz (<code>lowerMultiplicity = 1</code>).\n</li><li>Das Vorhandensein der Moduldefinition selbst ist im Gesamtsystem optional bis maximal einfach (<code>[0..1]</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8254bfb7575d25bf", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR ECU-Konfigurations-Klassendiagramm (UML-Metamodell nach Ecuc-Schema) kombiniert mit einer tabellarischen Moduldefinition für das Classic-Platform-Basiselement <code>LinNm</code> (LIN Network Management). Die Darstellung definiert die hierarchische Container-Struktur der Konfigurationsparameter auf oberster Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Metadatentabellen und eine dreistufige Kompositionskette von Konfigurationselementen:</p>\n<ul class=\"fig-list\"><li>Kopfzeile: Modulname <code>LinNm</code>, Modulbeschreibung „Configuration Parameters for the Lin Nm module.“.\n</li><li>Tabelle „Included Containers“:\n<ul class=\"fig-list\"><li><code>LinNmGlobalConfig</code>: Multiplicity 1, Scope / Dependency „This container contains the global configuration parameter of the LinNm.“.\n</li></ul>\n</li><li>UML-Klassenhierarchie:\n<ul class=\"fig-list\"><li><code>LinNm : EcucModuleDef</code>: Wurzelmoduldefinition mit Attributen <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li>Kompositionsbeziehung mit Rollenbezeichnung <code>+container</code> zu <code>LinNmGlobalConfig : EcucParamConfContainerDef</code>.\n</li><li>Kompositionsbeziehung mit Rollenbezeichnung <code>+subContainer</code> von <code>LinNmGlobalConfig</code> zu <code>LinNmChannelConfig : EcucParamConfContainerDef</code> mit Attributen <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungssemantik oder Laufzeitsequenzen. Die Struktur definiert die Kardinalitätsgrenzen und Schachtelungsregeln für die Instanziierung zur Generierungs-/Konfigurationszeit: Ein <code>LinNm</code>-Modul enthält genau einen globalen Konfigurationscontainer <code>LinNmGlobalConfig</code>, welcher wiederum mindestens einen oder mehrere (<code>1..*</code>) kanalspezifische Container (<code>LinNmChannelConfig</code>) als Sub-Container umfasst.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsspezifikation für AUTOSAR-Werkzeugketten und den LIN-NM-Stack:</p>\n<ul class=\"fig-list\"><li><code>LinNmGlobalConfig</code> ist obligatorisch (<code>Multiplicity = 1</code>).\n</li><li><code>LinNmChannelConfig</code> erfordert für jeden angebundenen LIN-Cluster mindestens eine Instanz (<code>lowerMultiplicity = 1</code>).\n</li><li>Das Vorhandensein der Moduldefinition selbst ist im Gesamtsystem optional bis maximal einfach (<code>[0..1]</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-77043be8cb431191", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR ECU-Konfigurations-Klassendiagramm (UML-Metamodell nach Ecuc-Schema) kombiniert mit einer tabellarischen Moduldefinition für das Classic-Platform-Basiselement <code>LinNm</code> (LIN Network Management). Die Darstellung definiert die hierarchische Container-Struktur der Konfigurationsparameter auf oberster Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Metadatentabellen und eine dreistufige Kompositionskette von Konfigurationselementen:</p>\n<ul class=\"fig-list\"><li>Kopfzeile: Modulname <code>LinNm</code>, Modulbeschreibung „Configuration Parameters for the Lin Nm module.“, <code>Post-Build Variant Support</code>: <code>false</code>.\n</li><li>Tabelle „Included Containers“:\n<ul class=\"fig-list\"><li><code>LinNmGlobalConfig</code>: Multiplicity 1, Scope / Dependency „This container contains the global configuration parameter of the LinNm.“.\n</li></ul>\n</li><li>UML-Klassenhierarchie:\n<ul class=\"fig-list\"><li><code>LinNm : EcucModuleDef</code>: Wurzelmoduldefinition mit Attributen <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li>Kompositionsbeziehung mit Rollenbezeichnung <code>+container</code> zu <code>LinNmGlobalConfig : EcucParamConfContainerDef</code>.\n</li><li>Kompositionsbeziehung mit Rollenbezeichnung <code>+subContainer</code> von <code>LinNmGlobalConfig</code> zu <code>LinNmChannelConfig : EcucParamConfContainerDef</code> mit Attributen <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungssemantik oder Laufzeitsequenzen. Die Struktur definiert die Kardinalitätsgrenzen und Schachtelungsregeln für die Instanziierung zur Generierungs-/Konfigurationszeit: Ein <code>LinNm</code>-Modul enthält genau einen globalen Konfigurationscontainer <code>LinNmGlobalConfig</code>, welcher wiederum mindestens einen oder mehrere (<code>1..*</code>) kanalspezifische Container (<code>LinNmChannelConfig</code>) als Sub-Container umfasst.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsspezifikation für AUTOSAR-Werkzeugketten und den LIN-NM-Stack:</p>\n<ul class=\"fig-list\"><li><code>Post-Build Variant Support</code> ist auf <code>false</code> festgelegt; Post-Build-Varianten werden für die Modulkonfiguration nicht unterstützt.\n</li><li><code>LinNmGlobalConfig</code> ist obligatorisch (<code>Multiplicity = 1</code>).\n</li><li><code>LinNmChannelConfig</code> erfordert mindestens eine Kanalinstanz (<code>lowerMultiplicity = 1</code>).\n</li><li>Die Moduldefinition besitzt die Multiplizität <code>[0..1]</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-10984c76de922a6b", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR ECU-Konfigurations-Klassendiagramm (UML-Metamodell nach Ecuc-Schema) kombiniert mit einer tabellarischen Moduldefinition für das Classic-Platform-Basiselement <code>LinNm</code> (LIN Network Management). Die Darstellung definiert die hierarchische Container-Struktur der Konfigurationsparameter auf oberster Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Metadatentabellen und eine dreistufige Kompositionskette von Konfigurationselementen:</p>\n<ul class=\"fig-list\"><li>Kopfzeile:\n<ul class=\"fig-list\"><li><code>SWS Item</code>: <code>ECUC_LinNm_00029 :</code>\n</li><li><code>Module Name</code>: <code>LinNm</code>\n</li><li><code>Module Description</code>: „Configuration Parameters for the Lin Nm module.“\n</li><li><code>Post-Build Variant Support</code>: <code>false</code>\n</li><li><code>Supported Config Variants</code>: <code>VARIANT-LINK-TIME, VARIANT-PRE-COMPILE</code>\n</li></ul>\n</li><li>Tabelle „Included Containers“:\n<ul class=\"fig-list\"><li><code>LinNmGlobalConfig</code>: Multiplicity 1, Scope / Dependency „This container contains the global configuration parameter of the LinNm.“.\n</li></ul>\n</li><li>UML-Klassenhierarchie:\n<ul class=\"fig-list\"><li><code>LinNm : EcucModuleDef</code>: Wurzelmoduldefinition mit Attributen <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li>Kompositionsbeziehung mit Rollenbezeichnung <code>+container</code> zu <code>LinNmGlobalConfig : EcucParamConfContainerDef</code>.\n</li><li>Kompositionsbeziehung mit Rollenbezeichnung <code>+subContainer</code> von <code>LinNmGlobalConfig</code> zu <code>LinNmChannelConfig : EcucParamConfContainerDef</code> mit Attributen <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungssemantik oder Laufzeitsequenzen. Die Struktur definiert die Kardinalitätsgrenzen und Schachtelungsregeln für die Instanziierung zur Generierungs-/Konfigurationszeit: Ein <code>LinNm</code>-Modul enthält genau einen globalen Konfigurationscontainer <code>LinNmGlobalConfig</code>, welcher wiederum mindestens einen oder mehrere (<code>1..*</code>) kanalspezifische Container (<code>LinNmChannelConfig</code>) als Sub-Container umfasst.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsspezifikation für AUTOSAR-Werkzeugketten und den LIN-NM-Stack:</p>\n<ul class=\"fig-list\"><li>Eindeutig referenzierbares SWS-Element <code>ECUC_LinNm_00029</code>.\n</li><li>Unterstützte Konfigurationsvarianten sind strikt auf <code>VARIANT-LINK-TIME</code> und <code>VARIANT-PRE-COMPILE</code> beschränkt; Post-Build-Konfiguration ist unzulässig (<code>Post-Build Variant Support = false</code>).\n</li><li><code>LinNmGlobalConfig</code> ist obligatorisch (<code>Multiplicity = 1</code>).\n</li><li><code>LinNmChannelConfig</code> erfordert mindestens eine Kanalinstanz (<code>lowerMultiplicity = 1</code>).\n</li><li>Die Moduldefinition besitzt die Multiplizität <code>[0..1]</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-eee22bc00638ae2b", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR ECU-Konfigurations-Klassendiagramm (UML-Metamodell nach Ecuc-Schema) kombiniert mit einer tabellarischen Moduldefinition für das Classic-Platform-Basiselement <code>LinNm</code> (LIN Network Management). Die Darstellung definiert die hierarchische Container-Struktur der Konfigurationsparameter auf oberster Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Metadatentabellen und eine dreistufige Kompositionskette von Konfigurationselementen:</p>\n<ul class=\"fig-list\"><li>Kopfzeile:\n<ul class=\"fig-list\"><li><code>SWS Item</code>: <code>ECUC_LinNm_00029 :</code>\n</li><li><code>Module Name</code>: <code>LinNm</code>\n</li><li><code>Module Description</code>: „Configuration Parameters for the Lin Nm module.“\n</li><li><code>Post-Build Variant Support</code>: <code>false</code>\n</li><li><code>Supported Config Variants</code>: <code>VARIANT-LINK-TIME, VARIANT-PRE-COMPILE</code>\n</li></ul>\n</li><li>Tabelle „Included Containers“:\n<ul class=\"fig-list\"><li><code>LinNmGlobalConfig</code>: Multiplicity 1, Scope / Dependency „This container contains the global configuration parameter of the LinNm.“.\n</li></ul>\n</li><li>UML-Klassenhierarchie:\n<ul class=\"fig-list\"><li><code>LinNm : EcucModuleDef</code>: Wurzelmoduldefinition mit Attributen <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li><li>Kompositionsbeziehung mit Rollenbezeichnung <code>+container</code> zu <code>LinNmGlobalConfig : EcucParamConfContainerDef</code>.\n</li><li>Kompositionsbeziehung mit Rollenbezeichnung <code>+subContainer</code> von <code>LinNmGlobalConfig</code> zu <code>LinNmChannelConfig : EcucParamConfContainerDef</code> mit Attributen <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungssemantik oder Laufzeitsequenzen. Die Struktur definiert die Kardinalitätsgrenzen und Schachtelungsregeln für die Instanziierung zur Generierungs-/Konfigurationszeit: Ein <code>LinNm</code>-Modul enthält genau einen globalen Konfigurationscontainer <code>LinNmGlobalConfig</code>, welcher wiederum mindestens einen oder mehrere (<code>1..*</code>) kanalspezifische Container (<code>LinNmChannelConfig</code>) als Sub-Container umfasst.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsspezifikation für AUTOSAR-Werkzeugketten und den LIN-NM-Stack:</p>\n<ul class=\"fig-list\"><li>Eindeutig referenzierbares SWS-Element <code>ECUC_LinNm_00029</code>.\n</li><li>Unterstützte Konfigurationsvarianten sind strikt auf <code>VARIANT-LINK-TIME</code> und <code>VARIANT-PRE-COMPILE</code> beschränkt; Post-Build-Konfiguration ist unzulässig (<code>Post-Build Variant Support = false</code>).\n</li><li><code>LinNmGlobalConfig</code> ist obligatorisch (<code>Multiplicity = 1</code>).\n</li><li><code>LinNmChannelConfig</code> erfordert mindestens eine Kanalinstanz (<code>lowerMultiplicity = 1</code>).\n</li><li>Die Moduldefinition besitzt die Multiplizität <code>[0..1]</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-578963c34d036c12", "to": "FIG-8254bfb7575d25bf", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Tabellen-Layout der Sektion „Included Containers“: Die fehlerhafte Zeilentrennung im Containernamen („LinNmGlobalConfi“ mit nachfolgendem „g“ auf einer neuen Zeile) wurde korrigiert zu einzeiligem „LinNmGlobalConfig“.\n</li><li>Tabellenkopf: Die vertikale Ausrichtung und Zellengrenzen zwischen Header und Datenzeilen wurden bereinigt.\n</li></ul>"}, {"from": "FIG-8254bfb7575d25bf", "to": "FIG-77043be8cb431191", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Kopf-Metadatentabelle: Die Eigenschaft „Post-Build Variant Support“ mit dem Wert „false“ wurde hinzugefügt.\n</li></ul>"}, {"from": "FIG-77043be8cb431191", "to": "FIG-10984c76de922a6b", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Kopf-Metadatentabelle: Neue Zeile „SWS Item“ mit der Spezifikations-Kennung „ECUC_LinNm_00029 :“ hinzugefügt.\n</li><li>Kopf-Metadatentabelle: Neue Zeile „Supported Config Variants“ mit den Werten „VARIANT-LINK-TIME, VARIANT-PRE-COMPILE“ hinzugefügt.\n</li></ul>"}, {"from": "FIG-10984c76de922a6b", "to": "FIG-eee22bc00638ae2b", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
